// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address lrtConfigAddr) public {
        vm.assume(lrtConfigAddr != address(0));

        vm.startPrank(address(0x1234));

        try c.updateLRTConfig(lrtConfigAddr) {
            assertTrue(false, "Non-admin successfully changed config");
        } catch {
            assertTrue(true);
        }

        vm.stopPrank();
    }
}
